// Synthetic-only preparation. Replace with an approved consent store at deployment time.
const profile = {
  business: { name: 'Sunrise Dental Clinic (DEMO)', hours: 'Mon-Sat, 9am-7pm IST' },
  modules: { booking: true, lead_capture: true, order_status: false, payment_link: false }
};
const followup = {
  name: 'Anita (demo)',
  contact: '+919000000004',
  reminder_type: 'appointment_reminder',
  consent_status: 'granted',
  opt_in_expires_at: '2026-12-31',
  last_sent_at: '2026-01-14T09:00:00+05:30',
  demo_now_iso: '2026-01-15T09:00:00+05:30',
  appointment: { slot_id: 'SLOT-002', date: '2026-01-17', start: '11:30', service: 'Consultation' },
  channel: 'whatsapp_demo',
  correlation_id: 'DEMO-UR-FOLLOWUP-001'
};
// Templates MUST come from the client-approved template list; the demo map is fictional and never sent anywhere.
const approved_templates = {
  appointment_reminder: 'Reminder: {name}, you have {service} on {date} at {start}. Reply CANCEL to change it.',
  review_request: 'Thank you for visiting {business}! If you have a moment, a review helps us a lot: {review_link_on_file}.',
  recall: 'Hi {name}, it has been a while since your last visit. Would you like to book a check-up?'
};
const correlation_id = followup.correlation_id || 'DEMO-UNIVERSAL-REPLIER-FOLLOWUP-SAMPLE';
return [{ json: { ...followup, profile, approved_templates, correlation_id, _demo: true, _scenario: 'replier-followup' } }];

const d = $input.first().json;
const templates = d.approved_templates || {};
const missing = ['contact', 'reminder_type'].filter((key) => !String(d[key] || '').trim());
const consented = d.consent_status === 'granted';
const optInValid = Boolean(d.opt_in_expires_at) && String(d.opt_in_expires_at) >= String(d.demo_now_iso || '').slice(0, 10);
const templateApproved = Boolean(templates[d.reminder_type]);
const nowMs = new Date(String(d.demo_now_iso || Date.now())).getTime();
const lastMs = d.last_sent_at ? new Date(String(d.last_sent_at)).getTime() : 0;
const frequencyOk = !lastMs || nowMs - lastMs >= 20 * 60 * 60 * 1000;
const review = missing.length > 0 || !consented || !optInValid || !templateApproved || !frequencyOk;
return [{ json: { ...d, _validation: { status: review ? 'NEEDS_HUMAN_REVIEW' : 'READY', review_required: review, missing, reason: missing.length ? 'Required follow-up data is missing' : !consented ? 'Contact has not opted in' : !optInValid ? 'Opt-in has expired or is missing' : !templateApproved ? 'Reminder type is not in the approved template list' : !frequencyOk ? 'Frequency cap: last message was sent less than 20 hours ago' : 'Follow-up request validated' } } }];

const d = $input.first().json;
const v = d._validation || { status: 'NEEDS_HUMAN_REVIEW', review_required: true, reason: 'Validation output missing' };
const templates = d.approved_templates || {};
let message = '';
if (v.status === 'READY') {
  message = String(templates[d.reminder_type] || '')
    .replace('{name}', d.name || '')
    .replace('{service}', (d.appointment && d.appointment.service) || '')
    .replace('{date}', (d.appointment && d.appointment.date) || '')
    .replace('{start}', (d.appointment && d.appointment.start) || '')
    .replace('{business}', (d.profile && d.profile.business && d.profile.business.name) || '')
    .replace('{review_link_on_file}', 'approved link on file');
}
const followup_draft = {
  module: 'followup',
  template_used: v.status === 'READY' ? d.reminder_type : 'none',
  message_draft: v.status === 'READY' ? 'Draft only: ' + message : '',
  send: 'not_performed_in_demo',
  opt_in_note: 'Send only to contacts who opted in, using approved templates only.'
};
const correlation_id = d.correlation_id || 'DEMO-UNKNOWN';
const audit = { workflow: 'replier-followup', action: 'draft_only', record_id: d.contact || 'sample', correlation_id: correlation_id };
return [{ json: { ...d, status: v.status === 'READY' ? 'DRAFT_ONLY' : 'NEEDS_HUMAN_REVIEW', review_required: v.review_required, reason: v.reason, needs_human: v.review_required, followup_draft: followup_draft, action_draft: { reply: followup_draft.message_draft || 'Route to a human owner; never message without opt-in and an approved template.', owner: v.review_required ? 'human-review' : 'replier' }, audit } }];
